7\u0435\u043d\u0438\u044f (\u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b BAdam/LoRA, \u0441\u043f\u043b\u0438\u0442\u044b MathInstruct, \u0448\u0430\u0431\u043b\u043e\u043d \u043f\u0440\u043e\u043c\u043f\u0442\u0430) \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b; \u043e\u043d\u0438 \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 (\u0441\u0442\u0430\u0442\u044c\u044f BAdam, MathInstruct \u043d\u0430 HF, \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 PEFT) \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f.\n\n## 2) \u041f\u043e\u0434\u0445\u043e\u0434 \u043a \u0434\u0438\u0437\u0430\u0439\u043d\u0443 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 (\u043e\u0431\u0437\u043e\u0440)\n\n**\u0414\u0430\u0442\u0430\u0441\u0435\u0442 (MathInstruct, TIGER-Lab/MathInstruct).** \u0412\u0437\u044f\u0442\u044c \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0438\u0437 13 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 52k\u2013100k \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432 \u043a\u0430\u043a \u043a\u043e\u043c\u043f\u0440\u043e\u043c\u0438\u0441\u0441 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c\u044e \u0438 \u0431\u044e\u0434\u0436\u0435\u0442\u043e\u043c; \u043f\u043e\u043b\u043d\u044b\u0439 \u043e\u0431\u044a\u0451\u043c 260k \u2014 \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0431\u044e\u0434\u0436\u0435\u0442). \u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u2014 **\u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0443\u0442\u0435\u0447\u043a\u0438**: \u0438\u0437 \u0442\u0440\u0435\u0439\u043d\u0430 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u043f\u0440\u0438\u043c\u0435\u0440\u044b, \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435 \u0441 \u043e\u0446\u0435\u043d\u043e\u0447\u043d\u044b\u043c\u0438 \u0442\u0435\u0441\u0442\u0430\u043c\u0438 (GSM8K, MATH test \u0438 \u0434\u0440.) \u043f\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u0430; \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u0443\u0431\u0440\u0430\u0442\u044c \u0438\u0437 \u0442\u0440\u0435\u0439\u043d\u0430 \u0441\u0430\u043c\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 GSM8K/MATH, \u0435\u0441\u043b\u0438 \u043e\u0446\u0435\u043d\u043a\u0430 \u0438\u0434\u0451\u0442 \u043f\u043e \u0438\u0445 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u043c \u0442\u0435\u0441\u0442\u0430\u043c (\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u0432\u0437\u0433\u043b\u044f\u0434: \u043e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 held-out \u0442\u0435\u0441\u0442\u0430\u0445 \u043f\u0440\u0438 \u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0438 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u044b\u0445 \u0447\u0430\u0441\u0442\u0435\u0439 \u044d\u0442\u0438\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u2014 \u043d\u043e \u0442\u043e\u0433\u0434\u0430 \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u0442\u0435\u0441\u0442\u0430 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430). \u0420\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0435: train / val (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 95/5) \u0434\u043b\u044f early-stopping \u0438 \u0432\u044b\u0431\u043e\u0440\u0430 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432; \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0442\u0435\u0441\u0442\u044b \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 eval, \u043d\u0438 \u0432 \u043a\u043e\u0435\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u043d\u0435 \u0432 \u0442\u0440\u0435\u0439\u043d/\u0432\u0430\u043b.\n\n**Zero-shot \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043e\u0446\u0435\u043d\u043a\u0438.** \u0411\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0438: \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0435 \u2014 GSM8K test (\u22481319 \u0437\u0430\u0434\u0430\u0447), MATH test (\u22485000); \u043f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 1\u20132 \u0434\u043e\u043f. (AQuA, TheoremQA \u0438\u043b\u0438 MATH500 \u2014 \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043f\u043e \u0431\u044e\u0434\u0436\u0435\u0442\u0443). \u0415\u0434\u0438\u043d\u044b\u0439 for-\u0432\u0441\u0435\u0445 \u043f\u0440\u043e\u043c\u043f\u0442-\u0448\u0430\u0431\u043b\u043e\u043d (\u043d\u0430\u043f\u0440. `Question: ...\\nAnswer:`), \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0431\u0435\u0437 few-shot, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e \u0434\u043b\u044f \u043e\u0431\u043e\u0438\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432. \u0418\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430: \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0442\u043e\u0440 (regex \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u0447\u0438\u0441\u043b\u0430 / \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u0438 \u043f\u043e\u0441\u043b\u0435 \u043c\u0430\u0440\u043a\u0435\u0440\u0430 \u043e\u0442\u0432\u0435\u0442\u0430; \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0447\u0438\u0441\u0435\u043b: \u0437\u0430\u043f\u044f\u0442\u044b\u0435, \u0437\u043d\u0430\u043a\u0438 $, \u0434\u0440\u043e\u0431\u0438/LaTeX \u0434\u043b\u044f MATH), exact-match \u043f\u043e\u0441\u043b\u0435 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438. \u0412\u0435\u0441\u044c \u043f\u0430\u043a\u0435\u0442 eval \u2014 \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 harness \u0434\u043b\u044f BAdam \u0438 LoRA.\n\n**\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438.**\n- BAdam: \u0440\u0430\u0437\u043c\u0435\u0440 \u0431\u043b\u043e\u043a\u0430 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 (Block size, \u043d\u0430\u043f\u0440. 400M\u20131B \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432), **\u0440\u0435\u0436\u0438\u043c \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0431\u043b\u043e\u043a\u043e\u0432** (\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 BAdam vs \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439), \u0447\u0438\u0441\u043b\u043e \u0431\u043b\u043e\u043a\u043e\u0432 \u0437\u0430 \u0448\u0430\u0433 = `solo ratio \u03c0` \u2192 \u0434\u0432\u0430 \u0440\u0435\u0436\u0438\u043c\u0430: **block-wise Adam** (\u03c0\u00b7D \u0431\u043b\u043e\u043a\u043e\u0432 \u0437\u0430 \u0446\u0438\u043a\u043b; \u043f\u0440\u0438 \u03c0\u00b7D=1 \u2192 coordinate descent). \u042d\u0442\u043e \u0434\u0432\u0430 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430 BAdam, \u0438\u0445 \u0442\u043e\u0436\u0435 \u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0431\u043e\u0439.\n- LoRA: rank (\u043d\u0430\u043f\u0440. 8/16/64), alpha (\u043d\u0430\u043f\u0440. 2\u00b7rank), target modules (q_proj+v_proj vs \u0432\u0441\u0435 attention+MLP), \u0431\u0430\u0437\u043e\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c 4-bit (NF4+double quant) \u0438\u043b\u0438 8-bit (bitsandbytes) \u0434\u043b\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u0438 \u043d\u0430 70B.\n- \u041f\u043e\u043b\u043d\u044b\u0439 finetune \u2014 \u0432\u0435\u0440\u0445\u043d\u044f\u044f \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u044f (\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u0441\u043c. \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u0443 \u043d\u0438\u0436\u0435).\n- \u0411\u0430\u0437\u043e\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0431\u0435\u0437 \u0434\u043e\u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f (zero-shot) \u2014 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c.\n\n**\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u0438 \u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u044c.** \u041e\u0431\u0449\u0438\u0435 seeds (\u22653) \u0434\u043b\u044f BAdam \u0438 LoRA; **\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0434\u0430\u043d\u043d\u044b\u0445** (\u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 shuffle/seed \u0438 \u0431\u0430\u0442\u0447\u0438); **\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 token budget / \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432** (\u0430 \u043d\u0435 \u0447\u0438\u0441\u043b\u043e \u043e\u0431\u0443\u0447\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u2014 \u0438\u0445 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 BAdam \u0438 LoRA \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0438\u0430\u043b\u044c\u043d\u043e: BAdam \u0437\u0430 \u0446\u0438\u043a\u043b \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u0442 \u0432\u0441\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b, LoRA \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0430\u0434\u0430\u043f\u0442\u0435\u0440\u044b); \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 base checkpoint (\u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u0432\u0435\u0440\u0441\u0438\u044f Llama 3-70B); \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 eval harness, \u0434\u0435\u043a\u043e\u0434\u0435\u0440 \u0438 \u043f\u0440\u043e\u043c\u043f\u0442. \u0413\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u0430 (lr, betas, warmup, schedule) \u2014 \u0433\u0434\u0435 \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c\u043e, \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u0442\u044c; \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0432 \u043e\u043f\u0442\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0445 lr \u0440\u0435\u0436\u0438\u043c\u0430\u0445 \u0437\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c.\n\n**\u041c\u0435\u0442\u0440\u0438\u043a\u0438.** Accuracy \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0435 (mean \u00b1 std \u043f\u043e seeds + bootstrap CI); \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043c\u0435\u0436\u0434\u0443 seed (\u0440\u0430\u0437\u0431\u0440\u043e\u0441 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438); \u043f\u0438\u043a\u043e\u0432\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c (`torch.cuda.max_memory_allocated`); \u0432\u0440\u0435\u043c\u044f \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f (\u0441\u0442\u0435\u043d\u043e\u0432\u044b\u0435 \u0447\u0430\u0441\u044b \u0438 steps/s); \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0447\u0438\u0441\u043b\u043e \u043e\u0431\u0443\u0447\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432.\n\n**\u0410\u043d\u0430\u043b\u0438\u0437 (\u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f BAdam vs LoRA).** \u041d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0440\u0435\u0434\u043d\u0438\u0435: **\u043f\u043e\u043f\u0430\u0440\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430 matched seeds** (\u043f\u0430\u0440\u043d\u044b\u0439 t-\u0442\u0435\u0441\u0442 \u0438\u043b\u0438 Wilcoxon signed-rank \u043f\u043e \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044f\u043c \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 \u043e\u0434\u043d\u0438\u0445 \u0438 \u0442\u0435\u0445 \u0436\u0435 seeds), **bootstrap \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b** \u0438, \u043f\u0440\u0438 \u0436\u0435\u043b\u0430\u043d\u0438\u0438, **McNemar \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0430\u0439\u0442\u0435\u043c\u043e\u0432**, \u0447\u0442\u043e\u0431\u044b \u0443\u0432\u0438\u0434\u0435\u0442\u044c, \u043d\u0430 \u043a\u0430\u043a\u0438\u0445 \u0437\u0430\u0434\u0430\u0447\u0430\u0445 \u043a\u0442\u043e \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442. \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439, \u043e\u043f\u0440\u0430\u0432\u0434\u044b\u0432\u0430\u0435\u043c\u044b\u0439 \u043f\u0440\u0438 \u043c\u0430\u043b\u043e\u043c N \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 (\u043d\u0430\u043f\u0440. N=3 seeds): \u044f\u0432\u043d\u043e \u0443\u043a\u0430\u0437\u0430\u0442\u044c \u043c\u0430\u043b\u0443\u044e \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c, \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0438 CI, \u0430 \u043d\u0435 \u0447\u0435\u0440\u0435\u0437 \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u0439 p-value; \u0432\u044b\u0432\u043e\u0434 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u00abBAdam \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c / \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043b\u0443\u0447\u0448\u0435 \u043d\u0430 \u00b1X \u043f.\u043f. \u0441 CI [...]\u00bb, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0432\u044b\u0438\u0433\u0440\u044b\u0448.\n\n**\u0412\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c (Llama 3-70B).** \u041f\u0430\u043c\u044f\u0442\u044c: \u0432\u0435\u0441\u0430 fp16 \u2248 140 GB; 4-bit \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u2248 35\u201340 GB \u0432\u0435\u0441\u043e\u0432. BAdam \u0434\u0435\u0440\u0436\u0438\u0442 \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u044b \u0438 Adam-\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u0431\u043b\u043e\u043a\u0430: \u043f\u0440\u0438 block size 1B \u2248 +12\u201316 GB, \u043f\u043b\u044e\u0441 \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0438/\u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u044b \u043d\u0430 \u0431\u043b\u043e\u043a\u0430\u0445 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u044f \u2014 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 150\u2013160 GB \u043f\u0438\u043a\u043e\u0432\u043e \u0432 fp16 \u2192 \u043d\u0443\u0436\u043d\u043e 2\u20134 \u00d7 A100-80GB (\u0438\u043b\u0438 H100) \u0441 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435\u043c (FSDP/model-parallel), \u043b\u0438\u0431\u043e 4-bit \u0431\u0430\u0437\u0430. LoRA 4-bit \u0432\u043b\u0435\u0437\u0430\u0435\u0442 \u0432 1\u20132 \u00d7 80GB. **\u041f\u043e\u043b\u043d\u044b\u0439 finetune 70B** (\u2248 700GB\u20131TB+ \u0441 Adam-\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f\u043c\u0438) \u0431\u0435\u0437 \u043c\u043d\u043e\u0433\u043e\u0443\u0437\u043b\u043e\u0432\u043e\u0439 FSDP/DeepSpeed \u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u0435\u043d \u2014 \u0435\u0441\u043b\u0438 GPU-\u0431\u044e\u0434\u0436\u0435\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d, \u043f\u043e\u043b\u043d\u044b\u0439 finetune \u043b\u0438\u0431\u043e \u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f (\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438), \u043b\u0438\u0431\u043e \u0441\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043a \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c \u0443\u0437\u043b\u0430\u043c. \u0412\u0440\u0435\u043c\u044f: \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u2014 \u0442\u044b\u0441\u044f\u0447\u0438 \u0448\u0430\u0433\u043e\u0432: \u043d\u0430 1\u00d7H100 LoRA 4-bit \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e \u0434\u0435\u0441\u044f\u0442\u043a\u0438 \u0447\u0430\u0441\u043e\u0432, BAdam \u043d\u0430 fp16 \u2014 \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u0434\u043e\u0440\u043e\u0436\u0435 (\u0432 \u0441\u0442\u0430\u0442\u044c\u0435 BAdam \u0434\u043b\u044f 7B \u0432\u0440\u0435\u043c\u044f \u2248 LoRA), \u0434\u043b\u044f 70B \u0442\u043e\u0447\u043d\u0430\u044f \u0446\u0438\u0444\u0440\u0430 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430 \u0431\u0435\u0437 GPU. **\u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c:** \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0435\u0440\u0441\u0438\u0438 (transformers, peft, bitsandbytes, BAdam-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439, CUDA/cuDNN), \u0432\u0441\u0435 seeds \u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0438 \u0432 \u043a\u043e\u0434\u0435/\u043a\u043e\u043d\u0444\u0438\u0433\u0435, \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0435\u0440\u0441\u0438\u044e base checkpoint \u0438 \u0448\u0430\u0431\u043b\u043e\u043d \u043f\u0440\u043e\u043c\u043f\u0442\u0430.\n\n## 3) \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438\n\n1. **\u041d\u0435\u0442 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e GPU-\u0431\u044e\u0434\u0436\u0435\u0442\u0430** (\u0447\u0438\u0441\u043b\u043e/\u0442\u0438\u043f GPU \u043d\u0435 \u0437\u0430\u0434\u0430\u043d) \u2014 \u044d\u0442\u043e \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 \u0434\u043b\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u0438, \u0432\u044b\u0431\u043e\u0440\u0430 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 MathInstruct \u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e full finetune.\n2. \u041a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b BAdam (block size, solo ratio \u03c0, \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0431\u043b\u043e\u043a\u043e\u0432) \u0438 LoRA (rank/alpha, target modules) \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0445 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u2192 \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 BAdam \u0438 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0438 PEFT; \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435.\n3. \u041e\u0431\u044a\u0451\u043c \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 MathInstruct (52k/100k/260k) \u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u0442\u0435\u0441\u0442\u043e\u0432 \u2014 \u043d\u0430\u0448\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435, \u043d\u0435 \u043f\u0440\u0435\u0434\u043f\u0438\u0441\u0430\u043d\u043e.\n4. \u0421\u043e\u0441\u0442\u0430\u0432 \u043e\u0446\u0435\u043d\u043e\u0447\u043d\u044b\u0445 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u0432 (GSM8K+MATH \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b; 1\u20132 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u2014 \u043d\u0430 \u0432\u044b\u0431\u043e\u0440) \u043d\u0435 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d.\n5. \u041f\u043e\u043b\u043d\u044b\u0439 finetune 70B \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c \u0432 \u0431\u044e\u0434\u0436\u0435\u0442\u0435 \u2014 \u0442\u043e\u0433\u0434\u0430 \u0432\u0435\u0440\u0445\u043d\u044f\u044f \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u044f \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b \u0438\u043b\u0438 \u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f; \u044d\u0442\u043e \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044e \u00abBAdam \u043f\u0440\u043e\u0442\u0438\u0432 \u0432\u0435\u0440\u0445\u043d\u0435\u0439 \u0433\u0440\u0430\u043d\u0438\u0446\u044b\u00bb.\n6. \u0421\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0441\u0442\u044c \u043f\u0440\u0438 \u0440\u0430\u0437\u043d\u044b\u0445 \u0447\u0438\u0441\u043b\u0430\u0445 \u043e\u0431\u0443\u0447\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432: \u043e\u0441\u044c \u0443\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f \u2014 \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432 \u0438 \u0443\u0432\u0438\u0434\u0435\u043d\u043d\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b, \u0430 \u043d\u0435 \u0447\u0438\u0441\u043b\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432; \u044d\u0442\u043e \u043c\u0435\u0442\u043e\u0434\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435.\n7. \u0427\u0438\u0441\u043b\u0430 \u043f\u0430\u043c\u044f\u0442\u0438/\u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0434\u043b\u044f 70B \u2014 \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432\u044b\u0435 \u043e\u0446\u0435\u043d\u043a\u0438 \u0438\u0437 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445, \u0442\u043e\u0447\u043d\u044b\u0445 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u0431\u0435\u0437 GPU \u0438 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432 \u043d\u0435\u0442.\n8. Zero-shot \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432 \u2014 \u0441\u0430\u043c\u043e \u043f\u043e \u0441\u0435\u0431\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0448\u0443\u043c\u0430; \u043f\u043b\u0430\u043d \u043e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u044